    bias_ed003: 'バイアス',
    simuladorDesc_ed004: 'シミュレーターを開いて、実際の資金をリスクにさらす前に、時間の経過（セータ）やボラティリティのスパイク（ベガ）がポジションにどう影響するかをテストしてください。',
    abrirSimulador_ed005: 'シミュレーターを開く',
    edu_fundamentosComprarVsVende_6227e3cc: '基礎: オプションのBUY vs SELL',
    edu_todaOperacionConOpciones_4b806806: 'すべてのオプション取引には2つの当事者がいます。BUY(Long)する側はプレミアムを支払い権利を取得します。SELL(Short)する側はプレミアムを受け取り、行使された場合の義務を受け入れます。',
    edu_lasGriegas_0ebfaf86: 'グリークス',
    edu_lasGriegasCuantificanLa_560a7bae: 'グリークスは、さまざまな要因に対するプレミアムの感応度を定量化します。これらをマスターすることが、プロトレーダーとアマチュアを分ける要素です。',
    edu_moneynessItmAtmOtm_a4a14296: 'Moneyness: ITM / ATM / OTM (解説)',
    edu_laMoneynessIndicaLa_d33c00c2: 'MONEYNESSは、原資産の現在価格(Spot S)とStrike Kの関係を示します。オプションの本質的価値とその挙動を定義します。',
    edu_volatilidadImplicitaIv_9566fdd4: 'インプライド・ボラティリティ(IV)',
    edu_laIvEsEl_8e2ceb1e: 'IVは、将来の不確実性に対する市場の価格です。IVが高いとプレミアムは高くなり、IVが低いとプレミアムは安くなります。Deltaの次に最も重要な要素です。',
    edu_comoLeerElDiagrama_0e91a1f2: 'Payoffダイアグラムの読み方',
    edu_elGraficoDePayoff_4228af6d: 'Payoffグラフは、満期時の原資産価格(X軸)に対するPnL(Y軸)を示します。2つの重要なラインは、T+0(本日)とAt Expiry(満期)です。',
    edu_longCallBuyCall_b69bddbc: 'LONG CALL (BUY CALL) → プレミアムを支払います。Strike+プレミアムを超えて上昇すれば利益。最大損失 = 支払ったプレミアム。',
    edu_longPutBuyPut_0125f4de: 'LONG PUT (BUY PUT) → プレミアムを支払います。Strike−プレミアムを下回れば利益。最大損失 = 支払ったプレミアム。',
    edu_shortCallSellCall_46b9297a: 'SHORT CALL (SELL CALL) → プレミアムを受け取ります。Strike+プレミアムを超えて上昇すれば損失。最大損失 = 無制限(nakedの場合)。',
    edu_shortPutSellPut_cc28336a: 'SHORT PUT (SELL PUT) → プレミアムを受け取ります。Strike−プレミアムを下回れば損失。最大損失 = 0まで下落した場合Strike−プレミアム。',
    edu_regla802080_db62e282: '80/20ルール → オプションの約80%は価値がないまま満期を迎える → 統計的にはプレミアム売り手が勝つことが多いが、リスク/リワード比率は悪い。',
    edu_deltaCambioEnPrima_0791393e: 'Delta Δ → 原資産が$1動いた時のプレミアムの変化。CALL: 0〜+1。PUT: 0〜-1。',
    edu_thetaPerdidaDeValor_c24fe104: 'Theta Θ → 1日経過するごとのタイムバリューの減少。Longでは常にマイナス、Shortではプラス。',
    edu_vegaSensibilidadAlCambio_49f4d565: 'Vega ν → インプライド・ボラティリティ(IV)の変化に対する感応度。Longではプラス、Shortではマイナス。',
    edu_gammaVelocidadDeCambio_2647e1e9: 'Gamma Γ → Deltaの変化速度。ATM付近で最大。Long: Gammaはプラス。Short: Gammaはマイナス。',
    edu_rhoSensibilidadACambios_6dd807ab: 'Rho ρ → 金利変動に対する感応度。長期オプション(LEAPS)でのみ重要。',
    edu_call_094692fa: '── CALL ──',
    edu_itmInTheMoney_d20317a8: 'ITM (In-The-Money) → S > K。本質的価値あり = S−K。Delta > 0.5。「株式のような」挙動。',
    edu_atmAtTheMoney_638c9e7d: 'ATM (At-The-Money) → S ≈ K。本質的価値なし、タイムバリューのみ。Delta ≈ 0.5。最大のGammaとVega。',
    edu_otmOutOfThe_2b67777e: 'OTM (Out-of-The-Money) → S < K。本質的価値なし、タイムバリューのみ。Delta < 0.5。より安価だがよりリスクが高い。',
    edu_put_a27fa8fc: '── PUT ──',
    edu_itmInTheMoney_bfd445a5: 'ITM (In-The-Money) → S < K. 本質的価値あり = K−S。Delta < −0.5。',
    edu_atmAtTheMoney_793be97c: 'ATM (At-The-Money) → S ≈ K. 本質的価値なし、時間価値のみ。Delta ≈ −0.5。',
    edu_otmOutOfThe_71ddb79d: 'OTM (Out-of-The-Money) → S > K. 本質的価値なし、時間価値のみ。Delta > −0.5。',
    edu_cLculoDelPayoff_2fb38b8e: '── 満期時のPayoff計算 ──',
    edu_longCallPnlMax_e997a851: 'Long Call:  PnL = max(0, S−K) × 100 × 契約数 − 支払Prima × 100',
    edu_longPutPnlMax_80f585a4: 'Long Put:   PnL = max(0, K−S) × 100 × 契約数 − 支払Prima × 100',
    edu_shortCallPnlPrima_d573157a: 'Short Call: PnL = 受取Prima × 100 − max(0, S−K) × 100 × 契約数',
    edu_shortPutPnlPrima_47fd35c2: 'Short Put:  PnL = 受取Prima × 100 − max(0, K−S) × 100 × 契約数',
    edu_ivRankIvPercentile_da54acc4: 'IV Rank / IV Percentile → 現在のIVを過去(直近52週)と比較して相対化。',
    edu_crushPostEarningsLa_c269719f: '決算後のCrush → イベント後にIVが急落。買い手は方向が正しくても損失を被ることが多い。',
    edu_vegaLongVsShort_404de31c: 'Vega Long vs. Short → 買い手はIV上昇で利益、売り手はIV低下で利益。',
    edu_reglaPracticaComprarOpcio_98a9dbf8: '実践ルール: IVが低い時(IV Rank < 30)にBUY、IVが高い時(IV Rank > 50)にSELL。',
    edu_skewLasPutsOtm_02473640: 'Skew → OTMのPUTはOTMのCALLよりもIVが高い傾向(下落への恐怖)。',
    edu_lineaVerdeCurrentP_ecfc0457: '緑線(Current P&L) → Black-Scholesを用いた現時点での理論PnL(時間価値を含む)を各価格で表示。',
    edu_lineaBlancaPunteadaAt_8a5c4ef9: '白破線(At Expiry) → 満期まで保有した場合のPnL(時間価値なし)。',
    edu_lineaNaranjaSpotPrecio_de21f24f: 'オレンジ線(Spot) → 原資産の現在価格。主要な基準点。',
    edu_lineaVioletaBreakEven_9112e631: '紫線(Break-Even) → 満期時にPnL = 0となる損益分岐点。上回る/下回ると利益。',
    edu_zonaVerdeRangoDe_49e82b2d: '緑ゾーン → 利益が出る価格帯。赤ゾーン → 損失。',
    edu_zonasDeMoneynessNuevas_d71f9261: 'MONEYNESS ゾーン(新規) → 薄緑 = ITM、黄色 = ATM、薄赤 = OTM。各Strikeの位置を視覚化。',
    edu_laDiferenciaEntreAmbas_439232b3: '両線の差 = 外在価値(時間 + IV)。負のThetaにより毎日減少。',
    gd_leerElGrafico_01e33326: 'チャートの読み方',
    gd_laLineaAzulMuestra_94ffef2a: '青線は現在のP&L(T+0)を示します。白線は満期時のP&Lです。緑/赤のエリアは利益/損失ゾーンを示します。',
    gd_delta_2772f4ee: 'Delta Δ',
    gd_sensibilidadPor1De_937b8b0f: '$1の値動きに対する感応度。Delta 0.50 = 原資産が$1上昇すると+$0.50。',
    gd_theta_466abd04: 'Theta Θ',
    gd_decaimientoDiarioLosVende_98a6f4d5: '日次減衰。売り手はThetaを受け取り、買い手はそれを支払う。',
    gd_vega_f1e18b4a: 'Vega ν',
    gd_siIvSube1_c5b35b3e: 'IVが1%上昇すると、ポジションはVegaドル分の損益が発生。オプション購入 = long Vega。',
    gd_probBeneficioPop_819a0c8f: '利益確率 (PoP)',
    gd_probabilidadEstadisticaDe_afd82330: '対数正規分布に基づく、満期時にプラスで終了する統計的確率。',
    gd_riskReward_cc314889: 'Risk / Reward',
    gd_ratioDeMaxProfit_3ca6ffc1: 'Max Profit / Max Lossの比率。PoP 40%でR/R 2xの方が、PoP 70%でR/R 0.5xよりも収益性が高い場合がある。',
      entendido_c32b2b: '了解',
