    trendDowntrendName: '下降トレンド',
    trendDowntrendDesc: '価格が切り下がる高値と安値をつくる:戻すたびに前回より低い位置で失速する。自然なのは戻りを売る・空売りすることで、『安いから買う』ではない。早すぎる底値拾いは、口座を飛ばす最大級の失敗の一つ。',
    trendSidewaysName: 'レンジ',
    trendSidewaysDesc: '価格が支持線と抵抗線の間のレンジで横ばいに動き、方向感がない状態。戦略:下限近くで買い上限近くで売る、またはブレイクまで手を出さない。相場は6〜7割がレンジなので、ここで『トレードしない』判断も立派なスキル。',
