    indEMAName: 'EMA',
    indEMADesc: '指数移動平均:SMAと似ているが直近の価格を重く見るため、早く向きを変え価格に密着する。人気は9・20・50。速いトレード向きで、代わりにSMAよりダマシが多い。多くはEMAでエントリーを計り、200SMAで全体像を見る。',
