    basicsMicroTitle: 'マイクロ lot（0.01）',
    basicsMicroUnits: '1,000 units',
    basicsMicroDesc: 'ほとんどのブローカーで利用できる最小単位です。口座を壊すことなく学習するのに最適です。10 pip 逆行しても損失はわずか $1。最小リスクで実際の市場で戦略をテストするのに最適です。',
    basicsMicroTip: '管理されたリスクで実際の市場での戦略を検証するために使用してください。',
    basicsMiniTitle: 'ミニ lot（0.1）',
    basicsMiniUnits: '10,000 units',
    basicsMiniDesc: 'マイクロ lot の 10 倍。成長中の口座の標準サイズ。過度に集中することなく複数の同時ポジションに分散できます。',
    basicsMiniTip: '$1,000–$10,000 の資金を持つ中級トレーダーの理想的な出発点。',
    basicsStdTitle: 'スタンダード lot（1.0）',
    basicsStdUnits: '100,000 units',
    basicsStdDesc: '外為市場の基準単位。EUR/USD では各 pip が $10 動きます。SL が 50 pip の場合 $500 リスク — 1 回の取引で 1-2% のリスクのみにするには少なくとも $25,000–$50,000 が必要です。',
    basicsStdWarning: '小口座でスタンダード lot を使わないでください：1 回の取引のリスクが過大になります。',
    basicsMacroTitle: 'マクロ / ビッグ（10+ lot）',
    basicsMacroUnits: '1M+ units',
    basicsMacroDesc: '機関投資家の領域。銀行、ファンド、ヘッジファンドがこのサイズで取引します。100 lot では各 pip が $1,000 の価値を持ちます。これらのポジションはしばしば価格を動かし、チャートで見るサポート/レジスタンスを作り出します。',
    basicsMacroInfo: 'これらのサイズを知ることで、価格が特定のレベルを尊重する理由を理解するのに役立ちます。',
    basicsPosFormulaTitle: '最適なポジションサイズの計算方法',
    basicsPosFormulaLabel: 'ユニバーサル計算式',
    basicsPosFormula: 'Lots = (資金 × リスク%) ÷ (Pips_SL × Pip_Value)',
    basicsPosFormulaExLabel: 'Practical example:',
    basicsPosFormulaExDesc: 'Capital: $5,000 | Risk: 1% | SL: 50 pips',
    basicsPosFormulaExResult: 'Lots = ($5,000 × 0.01) ÷ (50 × $1) = 1.0 mini lot',
    basicsPosGuideTitle: 'Quick guide by capital',
    basicsPosGuideNote: '* Assuming SL of 100 pips in EUR/USD',
    basicsPosWarningTitle: '最も多い間違い：ポジションサイズが大きすぎる',
    basicsPosWarning: '「動きが確実そう」という理由で口座が $2,000 しかないのに 1 スタンダード lot を開くことは、20 pip の SL（−$200）で資金の 10% を 1 回の取引で失うことを意味します。常に最大許容リスク（1-2%）から lot を計算してください、逆にではありません。',
    basicsFaqPosTitle: 'よくある質問 — ポジションサイズ',
    basicsFaqPos1Q: 'トレードにおける lot とは何ですか？',
    basicsFaqPos1A: 'Lot は外為と CFD でポジションサイズを測定する標準単位です。1 スタンダード lot は基軸通貨 100,000 単位に相当します。この標準化により、pip 価値と各取引のリスクを簡単に計算できます。',
    basicsFaqPos2Q: 'どのサイズの lot から始めるべきですか？',
    basicsFaqPos2A: '口座が $1,000 未満の場合、マイクロ lot（0.01）から始めましょう。$1,000 から $10,000 の間はミニ lot（0.1）を使用してください。スタンダード lot は合理的なリスク管理（1 回の取引で 1-2% のみリスク）のために $10,000 以上の口座が必要です。',
    basicsFaqPos3Q: 'Leverage はポジションサイズにどう影響しますか？',
    basicsFaqPos3A: 'Leverage により、はるかに少ない資金でスタンダード lot（100,000 単位）を制御できます。1:100 では 1 lot に $1,000 のマージンのみ必要です。しかし leverage は利益も損失も同様に拡大します：EUR/USD で leverage 1:100 の 1 lot は pip あたり $10 の利益または損失です。',
    basicsFaqPos4Q: 'Pip 価値とは何で、どう計算しますか？',
    basicsFaqPos4A: 'Pip は価格の最小移動単位（EUR/USD では 0.0001）です。Pip 価値 = (0.0001 × lot × 100,000)、決済通貨建て。EUR/USD では：1 スタンダード lot → $10/pip | 1 ミニ lot → $1/pip | 1 マイクロ lot → $0.10/pip。',
    basicsFaqPos5Q: 'なぜ機関投資家は大きな lot を使うのですか？',
    basicsFaqPos5A: '投資ファンド、銀行、ヘッジファンドは何億ドルも動かします。100 スタンダード lot（1,000 万単位）では各 pip が $1,000 の価値を持ちます。この規模では、数 pip の価格移動が PnL で何万ドルもの意味を持ちます。だからこそ彼らのエントリーとエグジットはしばしばチャート上のサポート/レジスタンスとして見えます。',
    basicsSummaryTitle: 'まとめ：5 つの概念を合わせて',
